	always@(posedge clk) begin
		if(rst == 1)begin
			start8_counter	<=	0;
		end else begin
			if(r_state_16 == STATE_START | r_state_16 == STATE_PROCESSING)begin
				if(start8_counter == 15)begin
					start8_counter <= start8_counter;
				end else begin
					start8_counter <= start8_counter + 1;
